export type DashboardLocale = 'es' | 'en'

export const DASHBOARD_LOCALE_COOKIE = 'casterfly_locale'

export function normalizeDashboardLocale(value: string | null | undefined): DashboardLocale {
  return value === 'en' ? 'en' : 'es'
}

export const DASHBOARD_LOCALE_META: Record<DashboardLocale, { label: string; short: string }> = {
  es: { label: 'Español', short: 'ES' },
  en: { label: 'English', short: 'EN' },
}

