export function menuName(locale: DashboardLocale, name: string): string {
  return locale === 'en' ? MENU_NAME_EN[name] ?? name : name
}

export function sectionName(locale: DashboardLocale, name: string): string {
  return locale === 'en' ? SECTION_NAME_EN[name] ?? name : name
}

export function adminMenuName(locale: DashboardLocale, name: string): string {
  return locale === 'en' ? ADMIN_MENU_NAME_EN[name] ?? name : name
}

export function adminSectionName(locale: DashboardLocale, name: string): string {
  return locale === 'en' ? ADMIN_SECTION_NAME_EN[name] ?? name : name
}
